          "quote": "/PWM_OUT : J2.4(Pin_4,passive) R5.1(passive)"
        },
        {
          "source": "netlist",
          "quote": "PWM : J4.1(MISO,passive) R2.1(passive) R5.2(passive) U2.6(PB1,bidirectional) U3.6(PB1,bidirectional)"
        },
        {
          "source": "spice",
          "quote": "R5 /PWM_OUT PWM 1Meg"
        }
      ],
      "impact": "The fan's PWM input will not be pulled low effectively; with a typical 10kΩ pull-up in the fan, the low level will be ~4.95V, so PWM speed control will not work.",
      "confidence": 0.9
    }
